//! Zero-dependency `#![no_std]` structured GPU Shader IR → **Metal Shading Language (MSL 2.4)**
//! and **WGSL** emitter.
//!
//! Takes [`EntryDesc`] metadata generated by `#[gpu::vertex]`, `#[gpu::fragment]` and
//! `#[gpu::kernel]` and emits valid MSL 2.4 and WGSL with exact `[[buffer(N)]]` / `[[texture(N)]]`
//! / `[[sampler(N)]]` and `@group(0) @binding(N)` slots directly into any [`core::fmt::Write`]
//! sink (zero heap allocations, zero external dependencies).

use crate::entry::{EntryDesc, Field, FieldKind, Interp, Kind, Out, Stage, ValueTy};
use core::fmt::{self, Write};

/// Fixed-capacity stack-backed [`core::fmt::Write`] buffer for `#![no_std]` shader emission.
pub struct StackWriter<const N: usize> {
    buf: [u8; N],
    len: usize,
}

impl<const N: usize> StackWriter<N> {
    #[inline]
    pub const fn new() -> Self {
        Self { buf: [0u8; N], len: 0 }
    }

    #[inline]
    pub fn as_str(&self) -> &str {
        // SAFETY: `write_str` only copies valid UTF-8 slices into `self.buf[..self.len]`.
        unsafe { core::str::from_utf8_unchecked(&self.buf[..self.len]) }
    }

    #[inline]
    pub const fn len(&self) -> usize {
        self.len
    }

    #[inline]
    pub const fn is_empty(&self) -> bool {
        self.len == 0
    }

    #[inline]
    pub fn clear(&mut self) {
        self.len = 0;
    }
}

impl<const N: usize> Default for StackWriter<N> {
    #[inline]
    fn default() -> Self {
        Self::new()
    }
}

impl<const N: usize> Write for StackWriter<N> {
    fn write_str(&mut self, s: &str) -> fmt::Result {
        let bytes = s.as_bytes();
        if self.len + bytes.len() > N {
            return Err(fmt::Error);
        }
        self.buf[self.len..self.len + bytes.len()].copy_from_slice(bytes);
        self.len += bytes.len();
        Ok(())
    }
}

/// Shader IR types.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum IrTy {
    Void,
    Bool,
    F32,
    I32,
    U32,
    Vec2,
    Vec3,
    Vec4,
    UVec2,
    UVec3,
    UVec4,
    IVec2,
    IVec3,
    IVec4,
    Mat2,
    Mat3,
    Mat4,
    Struct(&'static str),
    Array(&'static IrTy, u32),
}

impl IrTy {
    #[inline]
    pub const fn from_value_ty(v: ValueTy) -> Self {
        match v {
            ValueTy::F32 => Self::F32,
            ValueTy::Vec2 => Self::Vec2,
            ValueTy::Vec3 => Self::Vec3,
            ValueTy::Vec4 => Self::Vec4,
            ValueTy::U32 => Self::U32,
            ValueTy::UVec2 => Self::UVec2,
            ValueTy::UVec3 => Self::UVec3,
            ValueTy::UVec4 => Self::UVec4,
            ValueTy::I32 => Self::I32,
            ValueTy::IVec2 => Self::IVec2,
            ValueTy::IVec3 => Self::IVec3,
            ValueTy::IVec4 => Self::IVec4,
        }
    }
}

/// A field in an [`IrStruct`].
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct IrField {
    pub name: &'static str,
    pub ty: IrTy,
}

/// A user-defined struct type shared between host and shader.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct IrStruct {
    pub name: &'static str,
    pub fields: &'static [IrField],
}

/// Unary operators.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum IrUnaryOp {
    Neg,
    Not,
    BitNot,
}

/// Binary operators.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum IrBinOp {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    And,
    Or,
    BitAnd,
    BitOr,
    BitXor,
    Shl,
    Shr,
}

/// Structured shader IR expression.
#[derive(Copy, Clone, Debug)]
pub enum IrExpr<'a> {
    LitF32(f32),
    LitU32(u32),
    LitI32(i32),
    LitBool(bool),
    Var(&'a str),
    Unary(IrUnaryOp, &'a IrExpr<'a>),
    Binary(IrBinOp, &'a IrExpr<'a>, &'a IrExpr<'a>),
    Field(&'a IrExpr<'a>, &'a str),
    Index(&'a IrExpr<'a>, &'a IrExpr<'a>),
    Construct(IrTy, &'a [IrExpr<'a>]),
    Call(&'a str, &'a [IrExpr<'a>]),
    Cast(IrTy, &'a IrExpr<'a>),
    Sample2d {
        tex: &'a str,
        smp: &'a str,
        uv: &'a IrExpr<'a>,
        level: Option<&'a IrExpr<'a>>,
    },
    Load2d {
        tex: &'a str,
        coord: &'a IrExpr<'a>,
        level: &'a IrExpr<'a>,
    },
    /// Element length of a storage buffer parameter (`&[T]` or `&RawOut<T>`).
    BufferLen(&'a str),
    /// Built-in compute thread coordinates (`<param>_global`, `<param>_local`, `<param>_group`).
    ThreadGlobal(&'a str),
    ThreadLocal(&'a str),
    ThreadGroup(&'a str),
}

/// Structured shader IR statement.
#[derive(Copy, Clone, Debug)]
pub enum IrStmt<'a> {
    Let {
        name: &'a str,
        ty: Option<IrTy>,
        mutable: bool,
        init: IrExpr<'a>,
    },
    Assign {
        target: IrExpr<'a>,
        value: IrExpr<'a>,
    },
    If {
        cond: IrExpr<'a>,
        then_body: &'a [IrStmt<'a>],
        else_body: &'a [IrStmt<'a>],
    },
    ForRange {
        var: &'a str,
        start: IrExpr<'a>,
        end: IrExpr<'a>,
        body: &'a [IrStmt<'a>],
    },
    While {
        cond: IrExpr<'a>,
        body: &'a [IrStmt<'a>],
    },
    WorkgroupBarrier,
    Discard,
    Return(Option<IrExpr<'a>>),
    Expr(IrExpr<'a>),
}

/// A helper function parameter.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct IrFnParam {
    pub name: &'static str,
    pub ty: IrTy,
}

/// A non-entry helper function in a [`ShaderModule`].
#[derive(Copy, Clone, Debug)]
pub struct IrFn<'a> {
    pub name: &'a str,
    pub params: &'a [IrFnParam],
    pub ret: IrTy,
    pub body: &'a [IrStmt<'a>],
}

/// An entry point body coupled with its macro-generated [`EntryDesc`] and resource element types.
#[derive(Copy, Clone, Debug)]
pub struct IrEntry<'a> {
    pub desc: &'a EntryDesc,
    /// Element or uniform type for each parameter in `desc.params` (same index order).
    /// Non-buffer parameters (built-ins, textures, samplers, varyings) may use `IrTy::Void`.
    pub param_types: &'a [IrTy],
    pub body: &'a [IrStmt<'a>],
}

/// Complete shader module ready to emit to MSL 2.4 or WGSL.
#[derive(Copy, Clone, Debug)]
pub struct ShaderModule<'a> {
    pub structs: &'a [IrStruct],
    pub helpers: &'a [IrFn<'a>],
    pub entries: &'a [IrEntry<'a>],
}

// ---------------------------------------------------------------------------
// MSL 2.4 Emitter
// ---------------------------------------------------------------------------

/// Emits `module` as **Metal Shading Language (MSL 2.4)** into `out`, with exact `[[buffer(N)]]`,
/// `[[texture(N)]]`, `[[sampler(N)]]` bindings matching [`EntryDesc`].
pub fn emit_msl(module: &ShaderModule<'_>, out: &mut dyn Write) -> fmt::Result {
    writeln!(out, "#include <metal_stdlib>")?;
    let uses_raytracing = module
        .entries
        .iter()
        .any(|e| e.desc.params.iter().any(|p| matches!(p.kind, Kind::Tlas)));
    if uses_raytracing {
        writeln!(out, "#include <metal_raytracing>")?;
    }
    writeln!(out, "using namespace metal;\n")?;

    for s in module.structs {
        writeln!(out, "struct {} {{", s.name)?;
        for f in s.fields {
            write!(out, "    ")?;
            write_msl_decl(out, f.ty, f.name)?;
            writeln!(out, ";")?;
        }
        writeln!(out, "}};\n")?;
    }

    for entry in module.entries {
        if let Out::Varyings(fields) = entry.desc.out {
            write_msl_varyings_struct(out, entry.desc.name, "out", fields)?;
        }
        for p in entry.desc.params {
            if let Kind::Varyings(fields) = p.kind {
                write_msl_varyings_struct(out, entry.desc.name, "in", fields)?;
            }
        }
    }

    for helper in module.helpers {
        write_msl_ty(out, helper.ret)?;
        write!(out, " {}(", helper.name)?;
        for (i, p) in helper.params.iter().enumerate() {
            if i > 0 {
                write!(out, ", ")?;
            }
            write_msl_decl(out, p.ty, p.name)?;
        }
        writeln!(out, ") {{")?;
        for stmt in helper.body {
            write_stmt(ShaderLang::Msl, out, None, stmt, 1)?;
        }
        writeln!(out, "}}\n")?;
    }

    for entry in module.entries {
        let d = entry.desc;
        match d.stage {
            Stage::Vertex => {
                write!(out, "vertex {}_out {}(", d.name, d.name)?;
            }
            Stage::Fragment => {
                write!(out, "fragment float4 {}(", d.name)?;
            }
            Stage::Compute { x, y, z } => {
                writeln!(out, "// workgroup_size({x}, {y}, {z})")?;
                write!(out, "kernel void {}(", d.name)?;
            }
        }

        let mut first = true;
        let sep = |out: &mut dyn Write, first: &mut bool| -> fmt::Result {
            if !*first {
                write!(out, ", ")?;
            }
            *first = false;
            Ok(())
        };

        for (i, p) in d.params.iter().enumerate() {
            let elem_ty = entry.param_types.get(i).copied().unwrap_or(IrTy::U32);
            match p.kind {
                Kind::VertexIndex => {
                    sep(out, &mut first)?;
                    write!(out, "uint {} [[vertex_id]]", p.name)?;
                }
                Kind::InstanceIndex => {
                    sep(out, &mut first)?;
                    write!(out, "uint {} [[instance_id]]", p.name)?;
                }
                Kind::Thread => {
                    sep(out, &mut first)?;
                    write!(
                        out,
                        "uint3 {}_global [[thread_position_in_grid]], \
                         uint3 {}_local [[thread_position_in_threadgroup]], \
                         uint3 {}_group [[threadgroup_position_in_grid]]",
                        p.name, p.name, p.name
                    )?;
                }
                Kind::Varyings(_) => {
                    sep(out, &mut first)?;
                    write!(out, "{}_in {} [[stage_in]]", d.name, p.name)?;
                }
                Kind::Uniform { .. } => {
                    sep(out, &mut first)?;
                    write!(out, "constant ")?;
                    write_msl_ty(out, elem_ty)?;
                    write!(out, "& {} [[buffer({})]]", p.name, p.slot.index)?;
                }
                Kind::Storage { .. } => {
                    sep(out, &mut first)?;
                    write!(out, "const device ")?;
                    write_msl_ty(out, elem_ty)?;
                    write!(out, "* {} [[buffer({})]]", p.name, p.slot.index)?;
                }
                Kind::RawOut { .. } => {
                    sep(out, &mut first)?;
                    write!(out, "device ")?;
                    write_msl_ty(out, elem_ty)?;
                    write!(out, "* {} [[buffer({})]]", p.name, p.slot.index)?;
                }
                Kind::Tlas => {
                    sep(out, &mut first)?;
                    write!(
                        out,
                        "metal::raytracing::instance_acceleration_structure {} [[buffer({})]]",
                        p.name, p.slot.index
                    )?;
                }
                Kind::Texture2d => {
                    sep(out, &mut first)?;
                    write!(out, "texture2d<float> {} [[texture({})]]", p.name, p.slot.index)?;
                }
                Kind::Sampler => {
                    sep(out, &mut first)?;
                    write!(out, "sampler {} [[sampler({})]]", p.name, p.slot.index)?;
                }
            }
        }

        if let Some(sizes) = d.sizes {
            sep(out, &mut first)?;
            write!(out, "constant uint* _gpu_sizes [[buffer({})]]", sizes.index)?;
        }

        writeln!(out, ") {{")?;
        for stmt in entry.body {
            write_stmt(ShaderLang::Msl, out, Some(d), stmt, 1)?;
        }
        writeln!(out, "}}\n")?;
    }

    Ok(())
}

fn write_msl_varyings_struct(out: &mut dyn Write, entry_name: &str, suffix: &str, fields: &[Field]) -> fmt::Result {
    writeln!(out, "struct {entry_name}_{suffix} {{")?;
    for f in fields {
        match f.kind {
            FieldKind::Position => {
                writeln!(out, "    float4 {} [[position]];", f.name)?;
            }
            FieldKind::Value { ty, interp } => {
                let loc = f.location.unwrap_or(0);
                write!(out, "    ")?;
                write_msl_ty(out, IrTy::from_value_ty(ty))?;
                match interp {
                    Interp::Perspective => writeln!(out, " {} [[user(loc{loc})]];", f.name)?,
                    Interp::Linear => writeln!(out, " {} [[user(loc{loc}), center_no_perspective]];", f.name)?,
                    Interp::Flat => writeln!(out, " {} [[user(loc{loc}), flat]];", f.name)?,
                }
            }
        }
    }
    writeln!(out, "}};\n")
}

fn write_msl_ty(out: &mut dyn Write, ty: IrTy) -> fmt::Result {
    match ty {
        IrTy::Void => write!(out, "void"),
        IrTy::Bool => write!(out, "bool"),
        IrTy::F32 => write!(out, "float"),
        IrTy::I32 => write!(out, "int"),
        IrTy::U32 => write!(out, "uint"),
        IrTy::Vec2 => write!(out, "float2"),
        IrTy::Vec3 => write!(out, "float3"),
        IrTy::Vec4 => write!(out, "float4"),
        IrTy::UVec2 => write!(out, "uint2"),
        IrTy::UVec3 => write!(out, "uint3"),
        IrTy::UVec4 => write!(out, "uint4"),
        IrTy::IVec2 => write!(out, "int2"),
        IrTy::IVec3 => write!(out, "int3"),
        IrTy::IVec4 => write!(out, "int4"),
        IrTy::Mat2 => write!(out, "float2x2"),
        IrTy::Mat3 => write!(out, "float3x3"),
        IrTy::Mat4 => write!(out, "float4x4"),
        IrTy::Struct(name) => write!(out, "{name}"),
        IrTy::Array(elem, n) => {
            write!(out, "array<")?;
            write_msl_ty(out, *elem)?;
            write!(out, ", {n}>")
        }
    }
}

fn write_msl_decl(out: &mut dyn Write, ty: IrTy, name: &str) -> fmt::Result {
    write_msl_ty(out, ty)?;
    write!(out, " {name}")
}

fn write_indent(out: &mut dyn Write, depth: usize) -> fmt::Result {
    for _ in 0..depth {
        write!(out, "    ")?;
    }
    Ok(())
}

#[derive(Copy, Clone)]
enum ShaderLang {
    Msl,
    Wgsl,
}

impl ShaderLang {
    fn write_expr(self, out: &mut dyn Write, desc: Option<&EntryDesc>, expr: &IrExpr<'_>) -> fmt::Result {
        match self {
            Self::Msl => write_msl_expr(out, desc, expr),
            Self::Wgsl => write_wgsl_expr(out, expr),
        }
    }
}

fn write_stmt(
    lang: ShaderLang,
    out: &mut dyn Write,
    desc: Option<&EntryDesc>,
    stmt: &IrStmt<'_>,
    depth: usize,
) -> fmt::Result {
    write_indent(out, depth)?;
    match stmt {
        IrStmt::Let { name, ty, mutable, init } => {
            match lang {
                ShaderLang::Msl => {
                    if !*mutable {
                        write!(out, "const ")?;
                    }
                    match ty {
                        Some(t) => write_msl_ty(out, *t)?,
                        None => write!(out, "auto")?,
                    }
                    write!(out, " {name}")?;
                }
                ShaderLang::Wgsl => {
                    write!(out, "{} {name}", if *mutable { "var" } else { "let" })?;
                    if let Some(t) = ty {
                        write!(out, ": ")?;
                        write_wgsl_ty(out, *t)?;
                    }
                }
            }
            write!(out, " = ")?;
            lang.write_expr(out, desc, init)?;
            writeln!(out, ";")
        }
        IrStmt::Assign { target, value } => {
            lang.write_expr(out, desc, target)?;
            write!(out, " = ")?;
            lang.write_expr(out, desc, value)?;
            writeln!(out, ";")
        }
        IrStmt::If { cond, then_body, else_body } => {
            write!(out, "if (")?;
            lang.write_expr(out, desc, cond)?;
            writeln!(out, ") {{")?;
            for s in *then_body {
                write_stmt(lang, out, desc, s, depth + 1)?;
            }
            write_indent(out, depth)?;
            if else_body.is_empty() {
                writeln!(out, "}}")
            } else {
                writeln!(out, "}} else {{")?;
                for s in *else_body {
                    write_stmt(lang, out, desc, s, depth + 1)?;
                }
                write_indent(out, depth)?;
                writeln!(out, "}}")
            }
        }
        IrStmt::ForRange { var, start, end, body } => {
            match lang {
                ShaderLang::Msl => write!(out, "for (uint {var} = ")?,
                ShaderLang::Wgsl => write!(out, "for (var {var}: u32 = ")?,
            }
            lang.write_expr(out, desc, start)?;
            write!(out, "; {var} < ")?;
            lang.write_expr(out, desc, end)?;
            match lang {
                ShaderLang::Msl => writeln!(out, "; {var} += 1u) {{")?,
                ShaderLang::Wgsl => writeln!(out, "; {var} = {var} + 1u) {{")?,
            }
            for s in *body {
                write_stmt(lang, out, desc, s, depth + 1)?;
            }
            write_indent(out, depth)?;
            writeln!(out, "}}")
        }
        IrStmt::While { cond, body } => {
            write!(out, "while (")?;
            lang.write_expr(out, desc, cond)?;
            writeln!(out, ") {{")?;
            for s in *body {
                write_stmt(lang, out, desc, s, depth + 1)?;
            }
            write_indent(out, depth)?;
            writeln!(out, "}}")
        }
        IrStmt::WorkgroupBarrier => match lang {
            ShaderLang::Msl => writeln!(out, "threadgroup_barrier(mem_flags::mem_threadgroup);"),
            ShaderLang::Wgsl => writeln!(out, "workgroupBarrier();"),
        },
        IrStmt::Discard => match lang {
            ShaderLang::Msl => writeln!(out, "discard_fragment();"),
            ShaderLang::Wgsl => writeln!(out, "discard;"),
        },
        IrStmt::Return(None) => writeln!(out, "return;"),
        IrStmt::Return(Some(e)) => {
            write!(out, "return ")?;
            lang.write_expr(out, desc, e)?;
            writeln!(out, ";")
        }
        IrStmt::Expr(e) => {
            lang.write_expr(out, desc, e)?;
            writeln!(out, ";")
        }
    }
}

fn write_f32_lit(out: &mut dyn Write, v: f32) -> fmt::Result {
    // Ensure a decimal point so MSL/WGSL always parse as float.
    let mut tmp = StackWriter::<32>::new();
    write!(&mut tmp, "{v}")?;
    let s = tmp.as_str();
    if s.contains('.') || s.contains('e') || s.contains('E') {
        write!(out, "{s}")
    } else {
        write!(out, "{s}.0")
    }
}

fn msl_builtin_name(name: &str) -> &str {
    match name {
        "lerp" => "mix",
        "frac" => "fract",
        "dpdx" => "dfdx",
        "dpdy" => "dfdy",
        "ln" => "log",
        other => other,
    }
}

fn storage_index_and_stride(desc: Option<&EntryDesc>, param_name: &str) -> Option<(usize, u32)> {
    let d = desc?;
    let mut storage_idx = 0usize;
    for p in d.params {
        match p.kind {
            Kind::Storage { stride } | Kind::RawOut { stride } => {
                if p.name == param_name {
                    return Some((storage_idx, stride));
                }
                storage_idx += 1;
            }
            _ => {}
        }
    }
    None
}

fn write_msl_expr(out: &mut dyn Write, desc: Option<&EntryDesc>, expr: &IrExpr<'_>) -> fmt::Result {
    match expr {
        IrExpr::LitF32(v) => write_f32_lit(out, *v),
        IrExpr::LitU32(v) => write!(out, "{v}u"),
        IrExpr::LitI32(v) => write!(out, "{v}"),
        IrExpr::LitBool(b) => write!(out, "{}", if *b { "true" } else { "false" }),
        IrExpr::Var(name) => write!(out, "{name}"),
        IrExpr::Unary(op, inner) => {
            let sym = match op {
                IrUnaryOp::Neg => "-",
                IrUnaryOp::Not => "!",
                IrUnaryOp::BitNot => "~",
            };
            write!(out, "({sym}")?;
            write_msl_expr(out, desc, inner)?;
            write!(out, ")")
        }
        IrExpr::Binary(op, lhs, rhs) => {
            write!(out, "(")?;
            write_msl_expr(out, desc, lhs)?;
            write!(out, " {} ", bin_op_str(*op))?;
            write_msl_expr(out, desc, rhs)?;
            write!(out, ")")
        }
        IrExpr::Field(base, field) => {
            write_msl_expr(out, desc, base)?;
            write!(out, ".{field}")
        }
        IrExpr::Index(base, idx) => {
            write_msl_expr(out, desc, base)?;
            write!(out, "[")?;
            write_msl_expr(out, desc, idx)?;
            write!(out, "]")
        }
        IrExpr::Construct(ty, args) => {
            write_msl_ty(out, *ty)?;
            if matches!(ty, IrTy::Struct(_)) {
                write!(out, "{{")?;
                for (i, a) in args.iter().enumerate() {
                    if i > 0 {
                        write!(out, ", ")?;
                    }
                    write_msl_expr(out, desc, a)?;
                }
                write!(out, "}}")
            } else {
                write!(out, "(")?;
                for (i, a) in args.iter().enumerate() {
                    if i > 0 {
                        write!(out, ", ")?;
                    }
                    write_msl_expr(out, desc, a)?;
                }
                write!(out, ")")
            }
        }
        IrExpr::Call(name, args) => {
            write!(out, "{}(", msl_builtin_name(name))?;
            for (i, a) in args.iter().enumerate() {
                if i > 0 {
                    write!(out, ", ")?;
                }
                write_msl_expr(out, desc, a)?;
            }
            write!(out, ")")
        }
        IrExpr::Cast(ty, inner) => {
            write_msl_ty(out, *ty)?;
            write!(out, "(")?;
            write_msl_expr(out, desc, inner)?;
            write!(out, ")")
        }
        IrExpr::Sample2d { tex, smp, uv, level } => {
            write!(out, "{tex}.sample({smp}, ")?;
            write_msl_expr(out, desc, uv)?;
            if let Some(lvl) = level {
                write!(out, ", level(")?;
                write_msl_expr(out, desc, lvl)?;
                write!(out, ")")?;
            }
            write!(out, ")")
        }
        IrExpr::Load2d { tex, coord, level } => {
            write!(out, "{tex}.read(uint2(")?;
            write_msl_expr(out, desc, coord)?;
            write!(out, "), ")?;
            write_msl_expr(out, desc, level)?;
            write!(out, ")")
        }
        IrExpr::BufferLen(name) => {
            if let Some((idx, stride)) = storage_index_and_stride(desc, name) {
                write!(out, "(_gpu_sizes[{idx}] / {stride}u)")
            } else {
                write!(out, "0u")
            }
        }
        IrExpr::ThreadGlobal(p) => write!(out, "{p}_global"),
        IrExpr::ThreadLocal(p) => write!(out, "{p}_local"),
        IrExpr::ThreadGroup(p) => write!(out, "{p}_group"),
    }
}

// ---------------------------------------------------------------------------
// WGSL Emitter
// ---------------------------------------------------------------------------

/// Emits `module` as **WGSL** into `out`, with exact `@group(0) @binding(N)` layout matching
/// [`EntryDesc::wgsl_binding`] and [`EntryDesc::wgsl_sizes_binding`].
pub fn emit_wgsl(module: &ShaderModule<'_>, out: &mut dyn Write) -> fmt::Result {
    for s in module.structs {
        writeln!(out, "struct {} {{", s.name)?;
        for f in s.fields {
            write!(out, "    {}: ", f.name)?;
            write_wgsl_ty(out, f.ty)?;
            writeln!(out, ",")?;
        }
        writeln!(out, "}}\n")?;
    }

    for entry in module.entries {
        if let Out::Varyings(fields) = entry.desc.out {
            write_wgsl_varyings_struct(out, entry.desc.name, "out", fields)?;
        }
        for p in entry.desc.params {
            if let Kind::Varyings(fields) = p.kind {
                write_wgsl_varyings_struct(out, entry.desc.name, "in", fields)?;
            }
        }
    }

    // Emit module-scope resource bindings for each entry.
    for entry in module.entries {
        let d = entry.desc;
        let mut any_binding = false;
        for (i, p) in d.params.iter().enumerate() {
            let Some((group, binding)) = d.wgsl_binding(i) else {
                continue;
            };
            any_binding = true;
            let elem_ty = entry.param_types.get(i).copied().unwrap_or(IrTy::U32);
            write!(out, "@group({group}) @binding({binding}) ")?;
            match p.kind {
                Kind::Uniform { .. } => {
                    write!(out, "var<uniform> {}: ", p.name)?;
                    write_wgsl_ty(out, elem_ty)?;
                    writeln!(out, ";")?;
                }
                Kind::Storage { .. } => {
                    write!(out, "var<storage, read> {}: array<", p.name)?;
                    write_wgsl_ty(out, elem_ty)?;
                    writeln!(out, ">;")?;
                }
                Kind::RawOut { .. } => {
                    write!(out, "var<storage, read_write> {}: array<", p.name)?;
                    write_wgsl_ty(out, elem_ty)?;
                    writeln!(out, ">;")?;
                }
                Kind::Tlas => {
                    writeln!(out, "var {}: acceleration_structure;", p.name)?;
                }
                Kind::Texture2d => {
                    writeln!(out, "var {}: texture_2d<f32>;", p.name)?;
                }
                Kind::Sampler => {
                    writeln!(out, "var {}: sampler;", p.name)?;
                }
                _ => {}
            }
        }
        if let Some((group, binding)) = d.wgsl_sizes_binding() {
            any_binding = true;
            writeln!(out, "@group({group}) @binding({binding}) var<storage, read> _gpu_sizes: array<u32>;")?;
        }
        if any_binding {
            writeln!(out)?;
        }
    }

    for helper in module.helpers {
        write!(out, "fn {}(", helper.name)?;
        for (i, p) in helper.params.iter().enumerate() {
            if i > 0 {
                write!(out, ", ")?;
            }
            write!(out, "{}: ", p.name)?;
            write_wgsl_ty(out, p.ty)?;
        }
        write!(out, ")")?;
        if helper.ret != IrTy::Void {
            write!(out, " -> ")?;
            write_wgsl_ty(out, helper.ret)?;
        }
        writeln!(out, " {{")?;
        for stmt in helper.body {
            write_stmt(ShaderLang::Wgsl, out, None, stmt, 1)?;
        }
        writeln!(out, "}}\n")?;
    }

    for entry in module.entries {
        let d = entry.desc;
        match d.stage {
            Stage::Vertex => writeln!(out, "@vertex")?,
            Stage::Fragment => writeln!(out, "@fragment")?,
            Stage::Compute { x, y, z } => writeln!(out, "@compute @workgroup_size({x}, {y}, {z})")?,
        }
        write!(out, "fn {}(", d.name)?;
        let mut first = true;
        let sep = |out: &mut dyn Write, first: &mut bool| -> fmt::Result {
            if !*first {
                write!(out, ", ")?;
            }
            *first = false;
            Ok(())
        };
        for p in d.params {
            match p.kind {
                Kind::VertexIndex => {
                    sep(out, &mut first)?;
                    write!(out, "@builtin(vertex_index) {}: u32", p.name)?;
                }
                Kind::InstanceIndex => {
                    sep(out, &mut first)?;
                    write!(out, "@builtin(instance_index) {}: u32", p.name)?;
                }
                Kind::Thread => {
                    sep(out, &mut first)?;
                    write!(
                        out,
                        "@builtin(global_invocation_id) {}_global: vec3<u32>, \
                         @builtin(local_invocation_id) {}_local: vec3<u32>, \
                         @builtin(workgroup_id) {}_group: vec3<u32>",
                        p.name, p.name, p.name
                    )?;
                }
                Kind::Varyings(_) => {
                    sep(out, &mut first)?;
                    write!(out, "{}: {}_in", p.name, d.name)?;
                }
                _ => {}
            }
        }
        write!(out, ")")?;
        match d.stage {
            Stage::Vertex => write!(out, " -> {}_out", d.name)?,
            Stage::Fragment => write!(out, " -> @location(0) vec4<f32>")?,
            Stage::Compute { .. } => {}
        }
        writeln!(out, " {{")?;
        for stmt in entry.body {
            write_stmt(ShaderLang::Wgsl, out, None, stmt, 1)?;
        }
        writeln!(out, "}}\n")?;
    }

    Ok(())
}

fn write_wgsl_varyings_struct(out: &mut dyn Write, entry_name: &str, suffix: &str, fields: &[Field]) -> fmt::Result {
    writeln!(out, "struct {entry_name}_{suffix} {{")?;
    for f in fields {
        match f.kind {
            FieldKind::Position => {
                writeln!(out, "    @builtin(position) {}: vec4<f32>,", f.name)?;
            }
            FieldKind::Value { ty, interp } => {
                let loc = f.location.unwrap_or(0);
                write!(out, "    @location({loc}) ")?;
                match interp {
                    Interp::Perspective => {}
                    Interp::Linear => write!(out, "@interpolate(linear) ")?,
                    Interp::Flat => write!(out, "@interpolate(flat) ")?,
                }
                write!(out, "{}: ", f.name)?;
                write_wgsl_ty(out, IrTy::from_value_ty(ty))?;
                writeln!(out, ",")?;
            }
        }
    }
    writeln!(out, "}}\n")
}

fn write_wgsl_ty(out: &mut dyn Write, ty: IrTy) -> fmt::Result {
    match ty {
        IrTy::Void => Ok(()),
        IrTy::Bool => write!(out, "bool"),
        IrTy::F32 => write!(out, "f32"),
        IrTy::I32 => write!(out, "i32"),
        IrTy::U32 => write!(out, "u32"),
        IrTy::Vec2 => write!(out, "vec2<f32>"),
        IrTy::Vec3 => write!(out, "vec3<f32>"),
        IrTy::Vec4 => write!(out, "vec4<f32>"),
        IrTy::UVec2 => write!(out, "vec2<u32>"),
        IrTy::UVec3 => write!(out, "vec3<u32>"),
        IrTy::UVec4 => write!(out, "vec4<u32>"),
        IrTy::IVec2 => write!(out, "vec2<i32>"),
        IrTy::IVec3 => write!(out, "vec3<i32>"),
        IrTy::IVec4 => write!(out, "vec4<i32>"),
        IrTy::Mat2 => write!(out, "mat2x2<f32>"),
        IrTy::Mat3 => write!(out, "mat3x3<f32>"),
        IrTy::Mat4 => write!(out, "mat4x4<f32>"),
        IrTy::Struct(name) => write!(out, "{name}"),
        IrTy::Array(elem, n) => {
            write!(out, "array<")?;
            write_wgsl_ty(out, *elem)?;
            write!(out, ", {n}>")
        }
    }
}

fn wgsl_builtin_name(name: &str) -> &str {
    match name {
        "lerp" => "mix",
        "frac" => "fract",
        "rsqrt" => "inverseSqrt",
        "ln" => "log",
        other => other,
    }
}

fn write_wgsl_expr(out: &mut dyn Write, expr: &IrExpr<'_>) -> fmt::Result {
    match expr {
        IrExpr::LitF32(v) => write_f32_lit(out, *v),
        IrExpr::LitU32(v) => write!(out, "{v}u"),
        IrExpr::LitI32(v) => write!(out, "{v}i"),
        IrExpr::LitBool(b) => write!(out, "{}", if *b { "true" } else { "false" }),
        IrExpr::Var(name) => write!(out, "{name}"),
        IrExpr::Unary(op, inner) => {
            let sym = match op {
                IrUnaryOp::Neg => "-",
                IrUnaryOp::Not => "!",
                IrUnaryOp::BitNot => "~",
            };
            write!(out, "({sym}")?;
            write_wgsl_expr(out, inner)?;
            write!(out, ")")
        }
        IrExpr::Binary(op, lhs, rhs) => {
            write!(out, "(")?;
            write_wgsl_expr(out, lhs)?;
            write!(out, " {} ", bin_op_str(*op))?;
            write_wgsl_expr(out, rhs)?;
            write!(out, ")")
        }
        IrExpr::Field(base, field) => {
            write_wgsl_expr(out, base)?;
            write!(out, ".{field}")
        }
        IrExpr::Index(base, idx) => {
            write_wgsl_expr(out, base)?;
            write!(out, "[")?;
            write_wgsl_expr(out, idx)?;
            write!(out, "]")
        }
        IrExpr::Construct(ty, args) => {
            write_wgsl_ty(out, *ty)?;
            write!(out, "(")?;
            for (i, a) in args.iter().enumerate() {
                if i > 0 {
                    write!(out, ", ")?;
                }
                write_wgsl_expr(out, a)?;
            }
            write!(out, ")")
        }
        IrExpr::Call(name, args) => {
            write!(out, "{}(", wgsl_builtin_name(name))?;
            for (i, a) in args.iter().enumerate() {
                if i > 0 {
                    write!(out, ", ")?;
                }
                write_wgsl_expr(out, a)?;
            }
            write!(out, ")")
        }
        IrExpr::Cast(ty, inner) => {
            write_wgsl_ty(out, *ty)?;
            write!(out, "(")?;
            write_wgsl_expr(out, inner)?;
            write!(out, ")")
        }
        IrExpr::Sample2d { tex, smp, uv, level } => match level {
            None => {
                write!(out, "textureSample({tex}, {smp}, ")?;
                write_wgsl_expr(out, uv)?;
                write!(out, ")")
            }
            Some(lvl) => {
                write!(out, "textureSampleLevel({tex}, {smp}, ")?;
                write_wgsl_expr(out, uv)?;
                write!(out, ", ")?;
                write_wgsl_expr(out, lvl)?;
                write!(out, ")")
            }
        },
        IrExpr::Load2d { tex, coord, level } => {
            write!(out, "textureLoad({tex}, ")?;
            write_wgsl_expr(out, coord)?;
            write!(out, ", ")?;
            write_wgsl_expr(out, level)?;
            write!(out, ")")
        }
        IrExpr::BufferLen(name) => write!(out, "arrayLength(&{name})"),
        IrExpr::ThreadGlobal(p) => write!(out, "{p}_global"),
        IrExpr::ThreadLocal(p) => write!(out, "{p}_local"),
        IrExpr::ThreadGroup(p) => write!(out, "{p}_group"),
    }
}

fn bin_op_str(op: IrBinOp) -> &'static str {
    match op {
        IrBinOp::Add => "+",
        IrBinOp::Sub => "-",
        IrBinOp::Mul => "*",
        IrBinOp::Div => "/",
        IrBinOp::Rem => "%",
        IrBinOp::Eq => "==",
        IrBinOp::Ne => "!=",
        IrBinOp::Lt => "<",
        IrBinOp::Le => "<=",
        IrBinOp::Gt => ">",
        IrBinOp::Ge => ">=",
        IrBinOp::And => "&&",
        IrBinOp::Or => "||",
        IrBinOp::BitAnd => "&",
        IrBinOp::BitOr => "|",
        IrBinOp::BitXor => "^",
        IrBinOp::Shl => "<<",
        IrBinOp::Shr => ">>",
    }
}
